496	interface GlobalArgs {
497	  dataFile: string;
498	  help: boolean;
499	  rest: string[];
500	}
501	
502	function splitGlobalArgs(argv: string[]): GlobalArgs {
503	  const result: GlobalArgs = {dataFile: DEFAULT_DATA_FILE, help: false, rest: []};
504	  for (let i = 0; i < argv.length; i++) {
505	    const a = argv[i];
506	    if (a === '-h' || a === '--help') {
507	      result.help = true;
508	    } else if (a === '--data') {
509	      const v = argv[++i];
510	      if (v === undefined) throw new UsageError('选项 --data 缺少数据文件路径');
511	      result.dataFile = v;
512	    } else if (a.startsWith('--data=')) {
513	      result.dataFile = a.slice('--data='.length);
514	      if (result.dataFile === '') throw new UsageError('选项 --data 缺少数据文件路径');
515	    } else {
516	      result.rest.push(a);
517	    }
518	  }
519	  return result;
520	}
