773	// 解析正整数次数（不接受 0、负数、小数与前导零）
774	function parseOccurrences(raw: string): number {
775	  if (!/^[1-9]\d*$/.test(raw)) {
776	    throw new BizError(`次数非法: “${raw}”，必须是正整数（含首项）`);
777	  }
778	  const n = Number(raw);
779	  if (n > MAX_OCCURRENCES) {
780	    throw new BizError(`次数过大: “${raw}”，最大为 ${MAX_OCCURRENCES}`);
781	  }
782	  return n;
783	}
