785	interface PlannedMember {
786	  startRaw: string;
787	  endRaw: string;
788	  startMin: number;
789	  endMin: number;
790	}
791	
792	// 按周展开系列：每项相对前一项将起止时间同时后移 7 个营业地日历日，
793	// 时刻与跨日长度保持不变。任何一项超出四位年份范围即整体拒绝。
794	function planWeeklyMembers(startMin: number, endMin: number, count: number): PlannedMember[] {
795	  const members: PlannedMember[] = [];
796	  for (let i = 0; i < count; i++) {
797	    const s = startMin + i * 7 * 1440;
798	    const e = endMin + i * 7 * 1440;
799	    const startRaw = formatDateTime(s);
800	    const endRaw = formatDateTime(e);
801	    if (startRaw === null || endRaw === null) {
802	      const nth = i + 1;
803	      throw new BizError(
804	        `系列第 ${nth} 项（约第 ${nth} 周）的时间超出四位年份范围（${MIN_YEAR}-${MAX_YEAR}），无法创建：` +
805	          '请缩短次数或改选更早的首项时间',
806	      );
807	    }
808	    members.push({startRaw, endRaw, startMin: s, endMin: e});
809	  }
810	  return members;
811	}
