813	// 系列成员校验失败的聚合结构
814	interface MemberFailure {
815	  index: number; // 0 基
816	  startRaw: string;
817	  endRaw: string;
818	  gaps: Array<{id: string; r: ResourceRec}>;
819	  conflicts: Conflict[]; // 与既有有效预约的冲突
820	  internal: Array<{other: PlannedMember; otherIndex: number}>; // 与系列内其他成员的冲突
821	}
822	
823	async function cmdCreateSeries(args: string[]): Promise<void> {
824	  const {values, positionals} = parseFlags(args, ['resource', 'start', 'end', 'count'], ['resource']);
825	  if (positionals.length > 0) throw new UsageError(`create-series 不接受位置参数: ${positionals.join(' ')}`);
826	
827	  const resourceArgs = values.get('resource');
828	  if (!resourceArgs || resourceArgs.length === 0) throw new UsageError('至少需要一个 --resource');
829	  const startRaw = requireFlag(values, 'start');
830	  const endRaw = requireFlag(values, 'end');
831	  const count = parseOccurrences(requireFlag(values, 'count'));
832	
833	  const file = activeDataFile;
834	  const store = await loadStore(file);
835	
836	  const ids = resolveResourceIds(store, resourceArgs);
837	  const startMin = parseDateTime(startRaw, '首项开始时间');
838	  const endMin = parseDateTime(endRaw, '首项结束时间');
839	  if (endMin <= startMin) {
840	    throw new BizError(`首项结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
841	  }
842	
843	  // 先展开全部成员时间（含跨月、闰日、跨年、年份范围校验）
844	  const members = planWeeklyMembers(startMin, endMin, count);
845	
846	  // 逐项校验：开放覆盖、与既有有效预约冲突、与系列内其他成员冲突
847	  const failures: MemberFailure[] = [];
848	  for (let i = 0; i < members.length; i++) {
849	    const m = members[i];
850	    const gaps = findCoverageGaps(store, ids, m.startMin, m.endMin);
851	    const conflicts = findConflicts(store, ids, m.startMin, m.endMin);
852	    const internal: Array<{other: PlannedMember; otherIndex: number}> = [];
853	    for (let j = 0; j < members.length; j++) {
854	      if (j === i) continue;
855	      const o = members[j];
856	      if (o.startMin < m.endMin && m.startMin < o.endMin) {
857	        internal.push({other: o, otherIndex: j});
858	      }
859	    }
860	    if (gaps.length > 0 || conflicts.length > 0 || internal.length > 0) {
861	      failures.push({index: i, startRaw: m.startRaw, endRaw: m.endRaw, gaps, conflicts, internal});
862	    }
863	  }
864	
865	  if (failures.length > 0) {
866	    // 按发生顺序报告所有失败项；任一项不满足则整批失败，不分配任何标识、不写文件
867	    const blocks = failures.map((f) => {
868	      const lines = [`第 ${f.index + 1} 项 ${f.startRaw} → ${f.endRaw}：`];
869	      if (f.gaps.length > 0) {
870	        lines.push('  开放不足资源:');
871	        for (const {id, r} of f.gaps) lines.push(`    - ${id}（${r.name}）`);
872	      }
873	      if (f.conflicts.length > 0) {
874	        lines.push('  与以下既有预约冲突:');
875	        for (const c of f.conflicts) {
876	          lines.push(
877	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
878	              `：共同资源 ${formatResourceIds(store, c.shared)}`,
879	          );
880	        }
881	      }
882	      if (f.internal.length > 0) {
883	        lines.push('  与系列内其他成员冲突:');
884	        for (const x of f.internal) {
885	          lines.push(
886	            `    - 第 ${x.otherIndex + 1} 项（${x.other.startRaw} → ${x.other.endRaw}）：双方时间重叠`,
887	          );
888	        }
889	      }
890	      return lines.join('\n');
891	    });
892	    throw new BizError(
893	      `系列创建失败：共 ${failures.length} 项不满足条件（按发生顺序），整批未创建：\n${blocks.join('\n')}`,
894	    );
895	  }
896	
897	  // 全部验证通过：分配一个系列标识与每项预约标识，一次性落盘。
898	  // 标识在此刻才生成，任何失败都不会推进计数。
899	  store.seriesSeq += 1;
900	  const seriesId = `S${String(store.seriesSeq).padStart(4, '0')}`;
901	  const assigned: Array<{id: string; m: PlannedMember}> = [];
902	  for (const m of members) {
903	    store.bookingSeq += 1;
904	    const id = `B${String(store.bookingSeq).padStart(4, '0')}`;
905	    store.bookings.push({
906	      id,
907	      resourceIds: ids,
908	      start: m.startRaw,
909	      end: m.endRaw,
910	      status: 'active',
911	      seriesId,
912	    });
913	    assigned.push({id, m});
914	  }
915	  store.series.push({id: seriesId});
916	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
917	  store.series.sort((a, b) => a.id.localeCompare(b.id));
